    if (f.mold) a.push({ text: tt('Mold on the tomatoes'), sub: tt('Tomato Farm'), go: 'tomato' });
    if (s.dust > 0.4 && s.flow.sun.up) a.push({ text: tt`Dusty panels (−${Math.round(s.dust * 75)}% power)`, sub: tt('Solar Field'), go: 'solar', kind: 'warn' });
