    for (const id of ['potato', 'tomato']) if (ripeIn(s, id) >= 2) a.push({ text: tt`${ripeIn(s, id)} racks ripe in the ${rn(id)}`, sub: tt('A ripe rack stops growing until you pick it'), go: id, kind: 'warn' });
