    const storeNeed = storeD.mat + (storeR.hole > 0 ? 1 : 0), fullByDay = F.sun.up && F.sun.toSunset > 4 && s.battery >= F.cap * 0.9 && F.net > 0;   // full, and still more coming in than going out
    const storeTip = fullByDay && storeR.built < 1 && s.mat >= storeNeed + bathKeep ? tt`The battery is ${s.battery >= F.cap - 1 ? tt('full') : tt('nearly full')}, so the extra sunshine is going to waste. <b>${storeR.hole > 0 ? tt('Patch and rebuild') : tt('Rebuild')} the Battery Store</b>: it holds ${Math.round(s.batteryCap * 0.4)} kWh more for the long night. Do that before you fix more panels.` : null;
